,"s":[7],"w":1,"x":"1у, 4"},{"p":["Толмач"],"s":[0]}],[{"p":["Леха"],"s":[13],"w":1,"x":"4у, 6"},{"p":["Денис"],"s":[11]}],[{"p":["Фил"],"s":[1]},{"p":["Арс"],"s":[5],"w":1,"x":"1у, 2"}],[{"p":["Даня"],"s":[3]},{"p":["Хвост"],"s":[8],"w":1}],[{"p":["Витёк"],"s":[2]},{"p":["Женёк В"],"s":[5],"w":1,"x":"2у, 2"}],[{"p":["Ахмед"],"s":[4]},{"p":["Махмуд"],"s":[5],"w":1,"x":"1у, 2"}]]}]},{"title":"1/4 финала","parts":[{"note":"пары — по посеву: первый по очкам 1/8 с восьмым и так далее","groups":[[{"p":["Шурик"],"s":[28],"w":1,"x":"9у, 9"},{"p":["Арс"],"s":[2]}],[{"p":["Леха"],"s":[18],"w":1,"x":"6у, 6"},{"p":["Махмуд"],"s":[9],"w":1}],[{"p":["Хвост"],"s":[37],"w":1,"x":"11у, 13"},{"p":["Женёк В"],"s":[35],"w":1}],[{"p":["Диман"],"s":[28],"w":1,"x":"8у, 9"},{"p":["Ден"],"s":[18],"w":1}]]}]},{"title":"1/2 финала","parts":[{"groups":[[{"p":["Хвост"],"s":[10],"w":1,"x":"3у, 3"},{"p":["Леха"],"s":[8],"w":1}],[{"p":["Шурик"],"s":[22],"w":1},{"p":["Диман"],"s":[22],"w":1,"x":"7у, 8"}]]}]},{"title":"Финал","parts":[{"groups":[[{"p":["Диман"],"s":[20],"w":1},{"p":["Хвост"],"s":[16]}]]}]}]}$arch$::jsonb, $arch${"title":"Положение о втором чемпионате ЕБЛ","price":[{"t":"Поход в баню","s":"от часа, пост в группе в тот же день","v":"+1"},{"t":"Уникальная","s":"первая в 2024 году для тебя","v":"+1"},{"t":"Ультрауникальная","s":"никто из лиги не был в ней в 2023–2024 годах","v":"+1"},{"t":"Компания","s":"3 и больше участников в одной бане","v":"+1"}],"places":[10,7,5,3,2,1],"places_note":"Место — по числу бань за неделю. Поделили места — делите и очки, с округлением до десятых: четверо на 5–8 местах получат по (2+1+0+0)/4 = 0,8. Если за неделю никто не был в бане, она не разыгрывается.","fine":[{"b":"Баня","t":"— помещение для термопроцедур, нагретое выше 50 °C, где ты раздет. Подходят городские бани, ночные сауны, фитнесы и аквапарки с саунами, домашние и разборные бани."},{"b":"Неделя","t":"заканчивается в воскресенье в 23:59 МСК: в баню нужно зайти и написать в группу в тот же день."},{"b":"Одна баня в сутки.","t":"Повторный поход в ту же баню в тот же день не засчитывается."},{"b":"Разные бани","t":"— разные здания или разряды с отдельным входом и билетом."},{"b":"Итог","t":"— сумма очков за все недели. При равенстве выше тот, у кого больше бань. Сезон — с 1 января по 31 декабря 2024; неделя 30–31 декабря очков за места не давала — только за походы."},{"b":"Споры","t":"решает Комиссия ЕБЛ на заседаниях в Василёвских банях. Таблицу ведёт участник, уполномоченный Комиссией."}],"items":["Чемпионат ЕБЛ — ежегодное соревнование, проводящееся Евразийской банной лигой (ЕБЛ) с целью популяризации бань, саун и apres-ban'.","В чемпионате принимают участие все участники группы ОУД. В чемпионате не могут принимать участие другие участники. Если участник вступает в группу ОУД в середине года, очки в зачет чемпионата ЕБЛ начинают ему начисляться с этого момента. Если участник покидает группу ОУД, очки в зачет чемпионата ЕБЛ перестают ему начисляться с этого момента.","Под баней понимается специализированное для термических процедур, нагретое выше 50 °C помещение, в котором участник пребывает в раздетом виде. К баням относятся как общественные (городские) бани, так и индивидуальные банные помещения, включая ночные сауны, фитнесы и аквапарки с саунами, домашние сауны и переносные (разборные) бани.","Очки в чемпионате ЕБЛ начисляются за поход в баню. Очки за данный поход начисляются игроку при выполнении следующих условий: 1) поход в баню длился не менее 1 часа, 2) это был первый поход в данную баню за данные сутки, 3) поход документирован постом любого из участников чемпионата в телеграм-группу в тот же день.","Подсчет очков проводится еженедельно. Баня попадает в неделю, если участник зашел в нее не позднее 23:59 МСК воскресенья и прислал в этот же день информацию в группу.","По каждому игроку каждую неделю подсчитывается количество посещенных бань. Участники ранжируются по убыванию в зависимости от общего количества посещенных бань за неделю. Участнику, занявшему первое место, начисляется 10 очков, второе место — 7 очков, третье место — 5 очков, четвертое место — 3 очка, пятое место — 2 очка, шестое место — 1 очко. Участникам, занявшим седьмое и последующее места, начисляется 0 очков. В случае, если участники поделили места, им начисляется среднее арифметическое от количества баллов за эти места с округлением до десятых. Например, если 4 участника заняли 5—8 места, им начисляются по (2 + 1 + 0 + 0)/4 = 0,8 очков. Участники, не посетившие ни одной бани, получают 0 очков.","В случае, если ни один из участников за неделю не посетил ни одной из бань, неделя исключается из розыгрыша.","Кроме того, очки начисляются за факт посещения бани. За каждое посещение бани участнику начисляется 1 очко. Очки получают в т. ч. те участники, которые получили 0 очков в розыгрыше общего количества бань.","В случае, если баня посещена группой, в которую входит 3 и более участников ЕБЛ, каждому участнику за такое посещение дополнительно начисляется по 1 очку.","Дополнительно подсчитывается количество посещенных каждым участником уникальных бань. Уникальными считаются бани, размещенные в разных зданиях, а также бани, размещенные в одном здании, но считающиеся разными разрядами (каждый разряд снабжен отдельным входом по отдельному билету). За каждую уникальную (в пределах 2024 года) посещенную баню участник получает еще 1 очко (т. е. суммарно за посещение такой бани в первый раз участник получает 2 очка).","Также очки начисляются за посещение ультрауникальных бань — тех, в которых ни один из участников ЕБЛ ранее не был в 2023—2024 гг. За ультрауникальную баню каждый из участников, посетивших ее группой впервые (в пределах одного дня) в ЕБЛ, получает еще одно очко. За такое посещение бани участник суммарно получит 3 очка.","Очки каждого участника за все недели в течение года складываются.","Победителем чемпионата объявляется участник, набравший максимальное количество очков в течение года. В случае равенства этого показателя победитель выявляется по дополнительному показателю — количеству посещенных в течение года бань.","Чемпионат длится с 1 января 2024 года по 31 декабря 2024 года. Неделя 30-31 декабря баллов за места не дает, очки за нее добавляются только по посещениям бань.","Все спорные ситуации разбираются на комиссии чемпионата ЕБЛ, проводящейся периодически в Василёвских банях. О дате проведения очередной комиссии участники чемпионата ЕБЛ извещаются по телеграм-каналу ОУД.","Турнирную таблицу ведет участник, уполномоченный комиссией чемпионата ЕБЛ","Награждение и простава победителей осуществляется на комиссии чемпионата ЕБЛ.","Распределение участников по местам с 24 на 25 ноября"]}$arch$::jsonb),
