,"10":10.0,"7":2.8,"5":0.3,"4":1.5},"week_baths":{"48":2,"45":1,"43":1,"42":1,"36":2,"35":2,"33":2,"32":1,"28":1,"23":1,"22":1,"21":1,"20":1,"16":1,"10":10,"7":1,"5":1,"4":2}},{"nick":"Alex B","total":62.0,"baths":50,"u":14,"week_pts":{"48":3.0,"47":0.5,"46":0.2,"35":1.0,"30":1.0,"28":0.2,"26":3.3,"22":3.3,"21":1.2,"19":0.2,"18":0.5,"16":2.5,"15":1.0,"13":0.6,"10":0.3,"9":5.0,"8":0.8,"6":4.0,"3":1.0,"2":2.5,"1":2.0},"week_baths":{"52":1,"51":1,"49":2,"48":6,"47":1,"46":1,"45":1,"43":1,"42":1,"37":1,"36":1,"35":2,"33":1,"31":1,"30":2,"29":1,"28":1,"26":2,"24":1,"22":2,"21":1,"19":1,"18":1,"16":2,"15":1,"13":1,"11":1,"10":1,"9":2,"8":1,"6":2,"4":1,"3":1,"2":2,"1":2}},{"nick":"Пашок","total":53.6,"baths":33,"u":8,"week_pts":{"43":2.8,"36":3.3,"32":10.0,"31":10.0,"30":5.0,"21":1.2,"15":4.0,"13":0.6,"8":0.8},"week_baths":{"45":1,"43":2,"42":2,"36":3,"33":1,"32":7,"31":7,"30":3,"25":1,"21":1,"15":2,"13":1,"8":1,"4":1}},{"nick":"Серёга","total":45.9,"baths":28,"u":3,"week_pts":{"48":5.0,"46":4.3,"45":0.3,"40":8.5,"39":10.0,"38":10.0,"36":0.3,"35":1.0,"27":0.5},"week_baths":{"48":7,"46":2,"45":2,"43":1,"40":3,"39":4,"38":4,"36":2,"35":2,"27":1}},{"nick":"Виталик","total":34.9,"baths":17,"u":13,"week_pts":{"50":3.0,"47":3.0,"46":0.2,"38":2.8},"week_baths":{"51":1,"50":4,"49":1,"48":1,"47":2,"46":1,"45":1,"43":1,"38":2,"37":1,"35":1,"34":1}},{"nick":"Дёс","total":31.2,"baths":15,"u":9,"week_pts":{"46":4.3,"29":0.8,"24":1.0,"23":0.6,"19":0.2,"18":3.3,"17":2.8,"12":0.3},"week_baths":{"46":2,"37":1,"33":1,"29":3,"24":2,"23":1,"19":1,"18":2,"17":1,"12":1}},{"nick":"Миша П","total":28.4,"baths":11,"u":7,"week_pts":{"40":3.3,"21":1.2,"13":8.5,"12":0.3,"2":1.0},"week_baths":{"52":1,"40":2,"37":1,"21":1,"13":4,"12":1,"2":1}},{"nick":"Криш","total":27.0,"baths":16,"u":4,"week_pts":{"23":0.6,"21":6.0,"20":2.2,"19":6.0,"16":0.2,"14":0.2,"10":0.3,"8":0.8,"7":2.8},"week_baths":{"37":1,"36":1,"29":2,"23":1,"21":2,"20":1,"19":3,"16":1,"14":1,"10":1,"8":1,"7":1}},{"nick":"Женёк З","total":24.4,"baths":11,"u":7,"week_pts":{"35":1.0,"6":1.0,"5":5.4,"3":1.0,"1":2.0},"week_baths":{"43":1,"37":1,"35":2,"6":1,"5":2,"4":1,"3":1,"1":2}},{"nick":"Симба","total":22.8,"baths":11,"u":11,"week_pts":{"40":0.1,"27":0.5,"14":0.2},"week_baths":{"50":1,"49":1,"40":1,"36":1,"34":1,"32":1,"30":1,"27":1,"25":1,"14":1,"11":1}},{"nick":"Данюс","total":18.5,"baths":14,"u":7,"week_pts":{"52":0.6,"47":0.5,"44":1.5,"40":0.1,"39":0.3,"37":1.5},"week_baths":{"52":2,"51":1,"49":1,"48":2,"47":1,"45":1,"44":2,"40":1,"39":1,"37":2}},{"nick":"Дор","total":12.3,"baths":6,"u":6,"week_pts":{"40":0.1,"28":0.2},"week_baths":{"50":1,"44":1,"40":1,"35":1,"31":1,"28":1}},{"nick":"Жанат","total":11.8,"baths":7,"u":4,"week_pts":{"40":0.1,"28":0.2,"20":2.2,"6":1.0,"5":0.3},"week_baths":{"52":1,"40":1,"33":1,"28":1,"20":1,"6":1,"5":1}},{"nick":"Саша П","total":2.1,"baths":1,"u":1,"week_pts":{"40":0.1},"week_baths":{"40":1}}]$arch$::jsonb, $arch${"winners":["Ахмед"],"cols":[{"title":"1/8 финала","parts":[{"groups":[[{"p":["Ден"],"s":[6],"w":1},{"p":["Криш"],"s":[0]}],[{"p":["Даня"],"s":[5],"w":1},{"p":["Толмач"],"s":[4]}],[{"p":["Витёк"],"s":[7],"w":1},{"p":["Серёга"],"s":[7]}],[{"p":["Шурик"],"s":[0]},{"p":["Диман"],"s":[6],"w":1}],[{"p":["Леха"],"s":[8],"w":1},{"p":["Дёс"],"s":[0]}],[{"p":["Женёк В"],"s":[3],"w":1},{"p":["Пашок"],"s":[0]}],[{"p":["Фил"],"s":[36]},{"p":["Ахмед"],"s":[42],"w":1}],[{"p":["Махмуд"],"s":[9],"w":1},{"p":["Alex B"],"s":[7]}]]}]},{"title":"1/4 финала","parts":[{"groups":[[{"p":["Ден"],"s":[20]},{"p":["Даня"],"s":[23],"w":1}],[{"p":["Витёк"],"s":[1]},{"p":["Диман"],"s":[10],"w":1}],[{"p":["Леха"],"s":[14]},{"p":["Женёк В"],"s":[28],"w":1}],[{"p":["Ахмед"],"s":[11],"w":1},{"p":["Махмуд"],"s":[6]}]]}]},{"title":"1/2 финала","parts":[{"groups":[[{"p":["Даня"],"s":[13]},{"p":["Диман"],"s":[19],"w":1}],[{"p":["Женёк В"],"s":[4]},{"p":["Ахмед"],"s":[17],"w":1}]]}]},{"title":"Финал","parts":[{"groups":[[{"p":["Диман"],"s":[35]},{"p":["Ахмед"],"s":[35],"w":1}]]},{"title":"За третье место","groups":[[{"p":["Даня"],"s":[4],"w":1},{"p":["Женёк В"],"s":[2]}]]}]}]}$arch$::jsonb, $arch${"title":"Положение о чемпионате ЕБЛ","price":[{"t":"Уникальная баня","s":"первая в 2023 году для тебя; за повторные походы очков не было","v":"+2"}],"places":[10,7,5,3,2,1],"places_note":"Место — по числу бань за неделю. Поделили места — делите и очки, с округлением до десятых: четверо на 5–8 местах получат по (2+1+0+0)/4 = 0,8. Если за неделю никто не был в бане, она не разыгрывается.","fine":[{"b":"Баня","t":"— помещение для термопроцедур, нагретое выше 50 °C, где ты раздет. Подходят общественные и частные бани, домашние сауны и разборные бани."},{"b":"Поход","t":"засчитывается, если длился от часа, был первым в эту баню за сутки и попал в группу не позже следующего дня."},{"b":"Разные бани","t":"— разные здания или официально разные разряды одного здания."},{"b":"Итог","t":"— сумма очков за все недели. При равенстве выше тот, у кого больше уникальных бань."},{"b":"Финал.","t":"По решению Комиссии в декабре мог пройти финал чемпионата: очки за него удваивались."},{"b":"Споры","t":"решает Комиссия ЕБЛ на заседаниях в Василёвских банях. Таблицу ведёт участник, уполномоченный Комиссией."}],"items":["Чемпионат ЕБЛ — ежегодное соревнование, проводящееся Евразийской банной лигой (ЕБЛ) с целью популяризации бань, саун и apres-ban'.","В чемпионате принимают участие все участники группы ОУД. В чемпионате не могут принимать участие другие участники. Если участник вступает в группу ОУД в середине года, очки в зачет чемпионата ЕБЛ начинают ему начисляться с этого момента. Если участник покидает группу ОУД, очки в зачет чемпионата ЕБЛ перестают ему начисляться с этого момента.","Под баней понимается специализированное для термических процедур, нагретое выше 50 °C помещение, в котором участник пребывает в раздетом виде. Бани включают как общественные бани, так и частные (индивидуальные) банные помещения, включая домашние сауны и переносные (разборные) бани.","Очки в чемпионате ЕБЛ начисляются за поход в баню. Очки за данный поход начисляются игроку при выполнении следующих условий: 1) поход в баню длился не менее 1 часа, 2) это был первый поход в данную баню за данные сутки, 3) поход документирован постом любого из участников чемпионата в телеграм-группу не позднее дня, следующего за посещением.","Подсчет очков проводится еженедельно.","По каждому игроку каждую неделю подсчитывается количество посещенных бань.","Участники ранжируются по убыванию в зависимости от общего количества посещенных бань за неделю. Участнику, занявшему первое место, начисляется 10 очков, второе место — 7 очков, третье место —5 очков, четвертое место — 3 очка, пятое место — 2 очка, шестое место — 1 очко. Участникам, занявшим седьмое и последующее места, начисляется 0 очков. В случае, если участники поделили места, им начисляется среднее арифметическое от количества баллов за эти места с округлением до десятых. Например, если 4 участника заняли 5—8 места, им начисляются по (2 + 1 + 0 + 0)/4 = 0,8 очков. Участники, не посетившие ни одной бани, получают 0 очков.","В случае, если ни один из участников за неделю не посетил ни одной из бань, неделя исключается из розыгрыша.","Дополнительно подсчитывается количество посещенных каждым участником уникальных бань. Уникальными считаются бани, размещенные в разных зданиях, а также бани, размещенные в одном здании, но официально считающиеся разными разрядами. За каждую уникальную (в пределах года) посещенную баню участник получает 2 очка. Очки получают в т. ч. те участники, которые получили 0 очков в розыгрыше общего количества бань.","Очки каждого участника за все недели в течение года складываются.","Победителем чемпионата объявляется участник, набравший максимальное количество очков в течение года. В случае равенства этого показателя победитель выявляется по дополнительному показателю — количеству уникальных бань в течение года.","Все спорные ситуации разбираются на комиссии чемпионата ЕБЛ, проводящейся периодически в Василёвских банях. О дате проведения очередной комиссии участники чемпионата ЕБЛ извещаются по телеграм-каналу.","Турнирную таблицу ведет участник, уполномоченный комиссией чемпионата ЕБЛ.","Награждение и простава победителей осуществляется на комиссии чемпионата ЕБЛ.","Решением комиссии в декабре может быть проведён финал чемпионата. Все очки, полученные за финал, удваиваются."]}$arch$::jsonb);
